```
using Stripe;
using Stripe.Checkout;
using System;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Threading.Tasks;

namespace StripeExample
{
    public class PaymentController : Controller
    {
        // Set your Stripe secret key
        private readonly string _stripeSecretKey = "YOUR_STRIPE_SECRET_KEY";

        [HttpPost]
        public async Task<IActionResult> MakePayment(string stripeToken, string customerEmail)
        {
            // Create a new Stripe customer
            var customerService = new StripeCustomerService(_stripeSecretKey);
            var customer = await customerService.CreateAsync(new CustomerCreateOptions
            {
                Email = customerEmail,
                Description = "Your customer"
            });

            // Create a new Stripe payment method (in this case, a card)
            var paymentMethodService = new StripePaymentMethodService(_stripeSecretKey);
            var paymentMethod = await paymentMethodService.CreateAsync(new PaymentMethodCreateOptions
            {
                Type = "card",
                Card = new PaymentMethodCardOptions
                {
                    Number = "4242424242424242",
                    ExpMonth = 12,
                    ExpYear = 2025,
                    Cvc = "123",
                }
            });

            // Set up the payment intent to charge the customer's card and set up a trial period
            var paymentIntentService = new StripePaymentIntentService(_stripeSecretKey);
            var paymentIntent = await paymentIntentService.CreateAsync(new PaymentIntentCreateOptions
            {
                Amount = 1000, // Charge the customer $10.00
                Currency = "usd",
                PaymentMethodTypes = new[] { "card" },
                SetupFutureUsage = "off_session",
                // Set up the trial period
                OffSession = new OffSessionCreateOptions
                {
                    Interval = "month",
                    Quantity = 1,
                    Amount = 100,
                }
            });

            // Confirm the payment intent to charge the customer's card
            await paymentIntentService.ConfirmAsync(paymentIntent.Id, new PaymentIntentConfirmOptions
            {
                PaymentMethod = paymentMethod.Id,
                // Set the payment intent to succeeded to mark the payment as successful
                PaymentIntent = new PaymentIntentModifyOptions
                {
                    PaymentIntentStatus = "succeeded",
                }
            });

            // Return a success message
            return Json(new { message = "Payment processed successfully" });
        }
    }
}
```
