    { label: 'Apple', value: 'apple' },
    { label: 'Banana', value: 'banana' },
    { label: 'Cherry', value: 'cherry' }
    // Add more suggestions here
  ];

  useEffect(() => {
    const updateSuggestions = () => {
      const inputValueLowercase = inputValue.toLowerCase();
      const filteredSuggestions = suggestionsList.filter((suggestion) => {
        return suggestion.label.toLowerCase().includes(inputValueLowercase);
      });
      setSuggestions(filteredSuggestions);
    };

    updateSuggestions();
  }, [inputValue]);

  const handleInputChange = (event) => {
    setInputValue(event.target.value);
  };

  const handleSuggestionSelect = (suggestion) => {
    setInputValue(suggestion.label);
    setSelectedSuggestion(suggestion);
  };

  return (
    <div>
      <input
        type="search"
        value={inputValue}
        onChange={handleInputChange}
        placeholder="Autocomplete me!"
      />
      {suggestions.length > 0 && (
        <ul>
          {suggestions.map((suggestion, index) => (
            <li key={index} onClick={() => handleSuggestionSelect(suggestion)}>
              {suggestion.label}
            </li>
          ))}
        </ul>
      )}
      {selectedSuggestion && (
        <p>
          You selected: {selectedSuggestion.label} ({selectedSuggestion.value})
        </p>
      )}
    </div>
  );
};

export default Autocomplete;
