```csharp
using System;
using System.Net;
using System.Net.Http;
using System.Text;

namespace HelloWorldHttpServer
{
    class Program
    {
        static void Main(string[] args)
        {
            HttpListener listener = new HttpListener();
            listener.Prefixes.Add("http://localhost:8080/hello");
            listener.Start();

            while (true)
            {
                HttpListenerContext context = listener.GetContext();
                HttpListenerRequest request = context.Request;

                if (request.URLicine == "/hello")
                {
                    string responseBody = "Hello";
                    context.Response.ContentType = "text/plain";
                    context.Response.ContentLength64 = responseBody.Length;
                    Stream responseStream = context.Response.OutputStream;
                    byte[] buffer = Encoding.ASCII.GetBytes(responseBody);
                    responseStream.Write(buffer, 0, buffer.Length);
                }
                else
                {
                    context.Response.StatusCode = 404;
                    context.Response.StatusDescription = "Not Found";
                }

                context.Response.Close();
            }
        }
    }
}
```
Ce code utilise l'objet `HttpListener` pour créer un serveur qui écoute les requêtes sur la page "/hello" au port 8080. Quand une requête est reçue, le code vérifie si la requête est pour la page "/hello". Si c'est le cas, il répondu avec le texte "Hello" en mettant le contenu-type à "text/plain". Si la requête n'est pas pour la page "/hello", il renvoie un code d'état 404 avec un message "Not Found".

