agent.transformMethod(method, new MethodTransformer() {
    public void transform(Method method) throws Exception {
        // Replace the original method implementation with a new one
        method.setImplementation(new MethodImpl() {
            public Object invoke(Object receiver, Object[] args) throws Exception {
                // Do something new
                System.out.println("Method transformed!");
                return null;
            }
        });
    }
