```java
import java.net.*;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

public class NetworkSniffer {
    public static void main(String[] args) {
        // Configuração do sniffer
        int port = 1234; // porta de captura
        InetSocketAddress address = new InetSocketAddress(InetAddress.getByName("192.168.0.1"), port); // interface de rede
        byte[] buffer = new byte[65536]; // tamanho do buffer de captura

        // Cria o socket e conecta no endereço de rede especificado
        Socket socket = new Socket();
        socket.connect(address);

        // Inicializa o buffer de captura
        socket.setReceiveBufferSize(buffer.length);

        // Modelo de receção de dados
        while (true) {

            // Recebe dados do buffer
            int bytesRead = socket.available();
            if (bytesRead > 0) {
                socket.read(buffer, 0, bytesRead);

                // Analisa o pacote recebido
                List<String> packets = new ArrayList<>();
                for (int i = 0; i < bytesRead; i++) {
                    String packet = new String(buffer, i, bytesRead - i, StandardCharsets.UTF_8);
                    packets.add(packet);
                }

                // Impressão dos pacotes recebidos
                System.out.println("Received packets: " + packets);
            }
        }
    }
}
```
Este código cria um socket para capturar pacotes de rede em uma interface de rede especificada (neste caso, `192.168.0.1`) e porta (`1234`). Ele também configura o tamanho do buffer de captura para uma quantidade razoável (`65536` bytes).

O código então entrou em um loop infinito, onde ele verifica se há dados disponíveis para serem lidos do buffer de captura. Se houver, ele lê os dados do buffer e os analisa como pacotes de rede.

