// Estructura de nodo del árbol binario
struct Node {
    int valor;
    Node* izquierda;
    Node* derecha;
};

// Prototipo de la función de búsqueda
Node* buscar(Node* raiz, int valorBuscado);

// Implementación de la función de búsqueda
Node* buscar(Node* raiz, int valorBuscado) {
    if (raiz == nullptr) {
        // No se encontró el valor en el árbol
        return nullptr;
    }

    if (raiz->valor == valorBuscado) {
        // Encontramos el valor, devolvemos la dirección del nodo
        return raiz;
    }

    if (raiz->valor < valorBuscado) {
        // Buscamos en el subárbol derecho
        return buscar(raiz->derecha, valorBuscado);
    } else {
        // Buscamos en el subárbol izquierdo
        return buscar(raiz->izquierda, valorBuscado);
    }
}
