class SessionManager {
  constructor() {
    this.user = null;
    this.accessToken = null;
    this.refreshToken = null;
    this.isLoggedIn = false;
  }

  async authenticate() {
    try {
      const clientId = 'YOUR_CLIENT_ID';
      const clientSecret = 'YOUR_CLIENT_SECRET';
      const redirectUri = 'http://localhost:3000';

      const googleAuth = new google.auth.GoogleAuth({
        // Scopes to request access for
        scope: 'https://www.googleapis.com/auth/userinfo.email',
        // Client ID and client secret, you can get these
        // from the Google Cloud Console, or by running:
        // `npm run gcloud`
        client_id: clientId,
        client_secret: clientSecret,
        // Redirect URI for authorization puppet.
        redirect_uri: redirectUri,
      });

      const authUrl = googleAuth.getAuthUrl();
      window.location.href = authUrl;

      const redirectUriMatch = window.location.href.match(new RegExp(redirectUri));

      if (redirectUriMatch) {
        const code = redirectUriMatch[1].split('=')[1];
        const tokenResponse = await googleAuth.getToken(code);
        this.accessToken = tokenResponse.access_token;
        this.refreshToken = tokenResponse.refresh_token;
        this.isLoggedIn = true;
      }
    } catch (err) {
      console.error(err);
    }
  }

  async logout() {
    this.user = null;
    this.accessToken = null;
    this.refreshToken = null;
    this.isLoggedIn = false;
    localStorage.removeItem('user');
  }

  async getUserInfo() {
    if (!this.isLoggedIn) return null;
    try {
      const url = `https://www.googleapis.com/oauth2/v2/userinfo`;
      const headers = {
        'Authorization': `Bearer ${this.accessToken}`,
        'Content-Type': 'application/json',
      };
      const response = await fetch(url, { headers });
      const userInfo = await response.json();
      this.user = userInfo;
      return this.user;
    } catch (err) {
      console.error(err);
      return null;
    }
  }
}
