Here is a basic implementation of a Tic Tac Toe AI in JavaScript:
```
// Define the game board as a 2D array
const board = [
  [1, 2, 3],
  [4, 5, 6],
  [7, 8, 9]
];

// Define the current player (X or O)
let currentPlayer = 'X';

// Define the game logic functions
function makeMove(row, col) {
  if (board[row][col] !== '.') {
    console.log('Invalid move, try again');
    return;
  }
  board[row][col] = currentPlayer;
  currentPlayer = currentPlayer === 'X' ? 'O' : 'X';
}

function checkWin() {
  for (let i = 0; i < 3; i++) {
    if (board[i][0] === board[i][1] && board[i][0] === board[i][2] && board[i][0] !== '.') {
      return board[i][0];
    }
    if (board[0][i] === board[1][i] && board[0][i] === board[2][i] && board[0][i] !== '.') {
      return board[0][i];
    }
  }
  if (board[0][0] === board[1][1] && board[0][0] === board[2][2] && board[0][0] !== '.') {
    return board[0][0];
  }
  if (board[0][2] === board[1][1] && board[0][2] === board[2][0] && board[0][2] !== '.') {
    return board[0][2];
  }
  return null;
}

// Define the AI logic using the minimax algorithm
function minimax(board, depth, isMaximizing) {
  let winner = checkWin();
  if (winner) {
    return winner === 'X' ? -1 : 1;
  }
  if (depth === 0) {
    return 0;
  }
  let bestScore = isMaximizing ? -Infinity : Infinity;
  for (let i = 0; i < 3; i++) {
    for (let j = 0; j < 3; j++) {
      if (board[i][j] === '.') {
        board[i][j] = isMaximizing ? 'O' : 'X';
        let score = minimax(board, depth - 1, !isMaximizing);
        board[i][j] = '.';
        if (isMaximizing && score > bestScore) {
          bestScore = score;
        } else if (!isMaximizing && score < bestScore) {
          bestScore = score;
        }
      }
    }
  }
  return bestScore;
}

// Define the AI's move-making function
function makeAiMove() {
  let bestscore = -Infinity;
  let bestMove = null;
  for (let i = 0; i < 3; i++) {
    for (let j = 0; j < 3; j++) {
      if (board[i][j] === '.') {
        board[i][j] = 'O';
        let score = minimax(board, 2, false);
        board[i][j] = '.';
        if (score > bestscore) {
          bestscore = score;
          bestMove = { row: i, col: j };
        }
      }
    }
  }
  makeMove(bestMove.row, bestMove.col);
}

// Start the game
console.log('You are playing as X, the AI is playing as O');
makeAiMove();

// Loop until the game is over
while (true) {
  // Get the user's move
  const row = parseInt(prompt('Enter the row number (1-3):'));
  const col = parseInt(prompt('Enter the column number (1-3):'));
  makeMove(row - 1, col - 1);

  // Check if the game is over
  let winner = checkWin();
  if (winner) {
    console.log(`The winner is ${winner}!`);
    break;
  }

  // Make the AI's move
  makeAiMove();
  winner = checkWin();
  if (winner) {
    console.log(`The winner is ${winner}!`);
    break;
  }
}
